The following code implements fizz-buzz. Rewrite the for loop to allow more number-word pairs without adding more if statements.

function fizzBuzz(value) {
    let result = [];
    for (let i = 1; i <= value; i++) {
        let output = '';
        if (i % 3 === 0) {
            output += 'Fizz';
        }
        if (i % 5 === 0) {
            output += 'Buzz';
        }
        result.push(output || i);
    }
    return result;
}

